"use strict";(self.webpackChunkportfolio=self.webpackChunkportfolio||[]).push([["710"],{4829(e,t,o){o.r(t),o.d(t,{assets:()=>l,contentTitle:()=>a,default:()=>c,frontMatter:()=>r,metadata:()=>n,toc:()=>h});var n=o(980),s=o(4848),i=o(8453);let r={title:"Where Will Tomorrow\u2019s Experienced Professionals Come From?",date:new Date("2026-11-10T00:00:00.000Z"),author:"Chinenye Anyasor",sidebar_position:1},a="Where Will Tomorrow\u2019s Experienced Professionals Come From?",l={authorsImageUrls:[void 0]},h=[];function d(e){let t={p:"p",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.p,{children:"For decades, organizations in different sectors have carefully set up systems that cover the supply, training, and eventual retention of entry-level employees. In some sectors, this system is formal and highly standardized, like graduate trainee programmes, which involve job rotations, mentorship, simulations and defined learning pathways. This is particularly popular in the banking sector. In other sectors, the system is less formal. In some cases, the mandatory one-year NYSC supplies entry-level workers, while training happens informally through intentional mentorship and training provided by assigned managers."}),"\n",(0,s.jsx)(t.p,{children:"These systems, whether formal or less formal, when done right, have been successful in producing solid entry-level employees who go on to become the experienced professionals needed to replace mid-level workers as they move up the career ladder or move on to other things. This is how organizations have ensured a cycle of continuity in the workforce."}),"\n",(0,s.jsx)(t.p,{children:"For example, my first professional job after school was in a multinational with over 400 employees. I worked as an HR intern in the Human Resources department. It turned out that a lot of the work I had to do involved using spreadsheets (Microsoft Excel), and I had no prior experience with the software. I had to learn. My manager recommended online resources, and with the help of the company\u2019s Data Analyst, I was able to get up to speed."}),"\n",(0,s.jsx)(t.p,{children:"I also remember being assigned work that involved a lot of research. I would spend hours moving from one website to another, looking for articles relevant to my research. I remember being advised to maintain an empty Word document where I could save relevant links and also use it for brainstorming. Sometimes, the work required me to compare employee benefits and prepare detailed reports for management. My drafts would usually go through several rounds of review before the final document was approved for presentation."}),"\n",(0,s.jsx)(t.p,{children:"On some days, I would spend all night preparing PowerPoint slides, designing graphics to celebrate employee milestones, or editing videos after a team bonding activity. All of these were in addition to the responsibilities in my actual job description."}),"\n",(0,s.jsx)(t.p,{children:"I will be honest: I hated the entry-level phase of my career. I hated the grunt work that came with it. It was not glamorous, but it taught me how to work. It taught me to use tools I was not familiar with before and to sit with the discomfort of not getting something right the first time until I did. It taught me how to synthesize information, think critically, and exercise good judgment. It taught me many of the things that make me a good mid-level professional today."}),"\n",(0,s.jsx)(t.p,{children:"This is the ROI organizations get for investing in entry-level workers: a continuous supply of experienced professionals to fill gaps as mid-level workers move up and senior professionals retire."}),"\n",(0,s.jsx)(t.p,{children:"Well, fast forward to today. AI has entered the conversation, with the capacity to give us far more for less in minutes. With the right prompts, research, PowerPoint slides, video editing, automation of repetitive tasks, data analysis, writing, document editing, graphic design, and much more can now be done in minutes."}),"\n",(0,s.jsx)(t.p,{children:"And organizations, in a bid to optimize for efficiency and minimize costs, introduced AI into the very system they created to ensure they always have capable talent."}),"\n",(0,s.jsx)(t.p,{children:"General tasks that were once associated with entry-level roles are now being handled by AI. In specific fields, AI has also changed the way work is done. For example, AI has been introduced into various aspects of recruitment and software development, where it has given rise to what is commonly called vibe coding. Today, AI can even join a meeting as a participant, give updates, receive feedback, and use that feedback to iterate on assigned work, much like an actual employee."}),"\n",(0,s.jsx)(t.p,{children:"The result is that, in some fields and organizations, AI is reducing the need for certain junior roles or the number of people required to perform tasks previously assigned to them. And where entry-level positions still exist, the nature of the work has changed."}),"\n",(0,s.jsx)(t.p,{children:"There is already some research pointing to this shift. A working paper by researchers at Stanford University's Digital Economy Lab, using payroll data covering millions of US workers, found that employment among young workers aged 22 to 25 in occupations highly exposed to AI was 19% below the level it would have reached if it had grown at the same rate as employment in less AI-exposed occupations. Interestingly, the researchers attributed much of this difference to reduced hiring of young workers rather than increased layoffs."}),"\n",(0,s.jsx)(t.p,{children:"A separate analysis by the Federal Reserve Bank of Dallas, using US Census Bureau data, found a similar pattern: employment among younger workers in highly AI-exposed occupations had declined, with fewer young people moving into these jobs."}),"\n",(0,s.jsx)(t.p,{children:"While these findings do not establish that AI is solely responsible for the decline, they point to a growing concern: the impact of AI may be felt not only through the jobs it replaces, but also through the entry-level opportunities organizations no longer create."}),"\n",(0,s.jsx)(t.p,{children:"So the question is, in light of the not-so-recent changes brought about by AI, how do we ensure continuity in the workforce when the system previously designed to train entry-level employees and develop solid professionals has been changed unintentionally?"}),"\n",(0,s.jsx)(t.p,{children:"In my opinion, I do not think the introduction of AI is the problem. The issue is that organizations have failed to go back to the drawing board to redesign the systems used to train entry-level employees and rethink how work is structured in light of AI usage. We need to find a way to ensure the coexistence of innovations such as AI and entry-level roles. It should never be one or the other, as is happening today."}),"\n",(0,s.jsx)(t.p,{children:"Also, the onus is not just on organizations. This responsibility extends to schools as well."}),"\n",(0,s.jsx)(t.p,{children:"The making of a solid professional does not start with or depend solely on the training provided to entry-level employees by organizations. It starts way before that, in school. Students who will be expected to use AI at work in the future should be encouraged to start using it in school. This preparation should begin long before they become entry-level employees. Yes, I know this is not straightforward. There are risks to consider, and that is a whole different conversation. The point is that school curricula should change as frequently as needed to accommodate the realities of the job market."}),"\n",(0,s.jsx)(t.p,{children:"I have also found that curriculum review practices vary across education systems. According to an OECD report, some countries undertake major curriculum reforms as needed, while others follow fixed cycles, commonly between five and ten years. In Nigeria, for instance, the NUC recommends that engineering and technology programmes be reviewed at least once every five years. However, given the pace of technological change and its impact on the job market, I think institutions need to pay closer attention to how frequently their curricula are reviewed, updated, and implemented."}),"\n",(0,s.jsx)(t.p,{children:"Anyway, all of this is to help us recognize that we all have a collective responsibility. The consequences of continuing on this path could be a future with retired senior professionals, few or no mid-level professionals to replace them, and unemployed entry-level workers."}),"\n",(0,s.jsx)(t.p,{children:"AI is not the enemy, and frankly, I think it is here to stay. So instead of spending time coming up with think pieces (no offence to those who write them) focused on telling entry-level workers how to adapt to today's market, we should all begin to think about the changes that need to happen at a systemic level to ensure that the workforce remains self-replenishing."})]})}function c(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},8453(e,t,o){o.d(t,{R:()=>r,x:()=>a});var n=o(6540);let s={},i=n.createContext(s);function r(e){let t=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),n.createElement(i.Provider,{value:t},e.children)}},980(e){e.exports=JSON.parse('{"permalink":"/portfolio/blog/Future-of-work","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/Future-of-work.md","source":"@site/blog/Future-of-work.md","title":"Where Will Tomorrow\u2019s Experienced Professionals Come From?","description":"For decades, organizations in different sectors have carefully set up systems that cover the supply, training, and eventual retention of entry-level employees. In some sectors, this system is formal and highly standardized, like graduate trainee programmes, which involve job rotations, mentorship, simulations and defined learning pathways. This is particularly popular in the banking sector. In other sectors, the system is less formal. In some cases, the mandatory one-year NYSC supplies entry-level workers, while training happens informally through intentional mentorship and training provided by assigned managers.","date":"2026-11-10T00:00:00.000Z","tags":[],"readingTime":6.43,"hasTruncateMarker":false,"authors":[{"name":"Chinenye Anyasor","key":null,"page":null}],"frontMatter":{"title":"Where Will Tomorrow\u2019s Experienced Professionals Come From?","date":"2026-11-10T00:00:00.000Z","author":"Chinenye Anyasor","sidebar_position":1},"unlisted":false,"prevItem":{"title":"A Few Versions of Myself Later","permalink":"/portfolio/blog/A-few-versions-of-myself-later"},"nextItem":{"title":"How Online Payments Work","permalink":"/portfolio/blog/How-online-payment-work"}}')}}]);